from re import match

from taf.rfrl.procedures.resources.python.logger import log_env_state
from taf.rfrl.procedures.resources.python.sw_update.exceptions import InvalidSwVersion
from taf.rfrl.procedures.resources.python.sw_update.sw_version.sw_version import SwVersion


class SbtsKnifeSwVersion(SwVersion):
    """ Represents SBTS knife software version """

    def __init__(self, raw):
        super().__init__(raw)
        self._knife_number = raw.split('_')[-1].split('T')[0]
        self._sbts_headers = {'9999': 'SBTS00', '9990': 'SBTS00'}

    @property
    def package(self) -> str:
        """
        Returns SW version in package name format, i.e.
        'SBTS00_ENB_9999_250805_1390544_release_BTSSM_downloadable_testpackage_T1_A54.zip'

        :return: package format of SW version, i.e. 'SBTS00_ENB_9999_250805_1390544_release_BTSSM_downloadable_A54.zip'
        :rtype: str
        """
        if self._package is None:
            sbts_header, _, head, mid, tail = self.raw.split('_')
            sbts_header = self._sbts_headers[head] if head in self._sbts_headers.keys() else sbts_header
            test = ''

            if self.raw.endswith('T1'):
                tail = tail.replace('T1', '')
                test = '_testpackage_T1'
            elif self.raw.endswith('T2'):
                tail = tail.replace('T2', '')
                test = '_testpackage_T2'

            tail = tail.zfill(7)

            self._package = (
                "{}_ENB_{}_{}_{}_release_BTSSM_downloadable{}_A54.zip".format(
                    sbts_header, head, mid, tail, test
                )
            )
        return self._package

    @property
    def packages_url(self) -> str:
        """
        Returns URL to all available packages for particular SW version.

        :return: url to all available packages for particular SW version, i.e.:
                 https://es-si-s3-z2.eecloud.nsn-net.net/knife-results/1390544/
        :rtype: str
        """
        if self._packages_url is None:
            self._packages_url = f'https://es-si-s3-z2.eecloud.nsn-net.net/knife-results/{self._knife_number}/'

        return self._packages_url

    @property
    def url(self) -> str:
        """
        Returns SW version in URL format.

        :return: SW version in URL format, i.e.:
                 'https://es-si-s3-z2.eecloud.nsn-net.net/knife-results/1390544/SBTS00_ENB_9999_230724_000016_release_
                  BTSSM_downloadable_testpackage_T1_A54.zip'
        :rtype: str
        """
        if self._url is None:
            package = self.package
            self._url = f'https://es-si-s3-z2.eecloud.nsn-net.net/knife-results/{self._knife_number}/{package}'
            log_env_state(f'{self.__class__.__name__} url: {self._url}')
        return self._url

    @property
    def checksum(self) -> str:
        """
        Returns checksum of SW package.

        :return: checksum of SW package
        :rtype: str
        """
        return self._checksum

    def _validate_raw(self, raw: str):
        """
        Checks whether given raw SW version number is correct.

        :param raw: SW version in raw format, i.e.:
         'SBTS00_ENB_9999_250805_1390544' for regular knife software version,
         'SBTS00_ENB_9999_250805_1390544T1' in case of test package 1
        :type raw: str

        :raises InvalidSwVersion: when given raw number is invalid
        """
        valid_raw_pattern = r'^SBTS[0-9A-R]{0,4}_ENB_[0-9]{4}_[0-9]{6}_[0-9]{7}(T[1-2])?$'

        if not match(valid_raw_pattern, raw):
            raise InvalidSwVersion('Cannot create {} from invalid raw input: {}'.format(self.__class__.__name__, raw))
